// Helper for error responses
fn err_response(status: StatusCode, msg: &str) -> Response {
    (status, Json(serde_json::json!({ "error": msg }))).into_response()
}

pub async fn upload_video(
    State(state): State<AppState>,
    mut multipart: Multipart,
) -> Result<impl IntoResponse, Response> {
    let mut title = None;
    let mut filename = None;
    let mut file_bytes = Vec::new();

    while let Some(field) = multipart.next_field().await.map_err(|e| {
        err_response(StatusCode::BAD_REQUEST, &format!("Multipart error: {}", e))
    })? {
        let name = field.name().unwrap_or("").to_string();
        if name == "title" {
            title = Some(field.text().await.unwrap_or_default());
        } else if name == "file" {
            filename = Some(field.file_name().unwrap_or("video.mp4").to_string());
            file_bytes = field.bytes().await.map_err(|e| {
                err_response(StatusCode::INTERNAL_SERVER_ERROR, &format!("Failed to read file chunk: {}", e))
            })?.to_vec();
        }
    }

    let file_name = filename.ok_or_else(|| err_response(StatusCode::BAD_REQUEST, "Missing file field"))?;
    let title_str = title.unwrap_or_else(|| file_name.clone());
    let size = file_bytes.len() as i64;

    if size == 0 {
        return Err(err_response(StatusCode::BAD_REQUEST, "Uploaded file is empty"));
    }

    // Create DB record (Pending)
    let video = state.video_service.create_video(&title_str, &file_name, size).await
        .map_err(|e| err_response(StatusCode::INTERNAL_SERVER_ERROR, &format!("Database error: {}", e)))?;

    // Save temporary raw file
    let ext = PathBuf::from(&file_name)
        .extension()
        .and_then(|s| s.to_str())
        .unwrap_or("mp4")
        .to_string();
        
    let temp_path = state.storage.get_upload_path(&video.id, &ext);
    
    fs::write(&temp_path, file_bytes).await.map_err(|e| {
        err_response(StatusCode::INTERNAL_SERVER_ERROR, &format!("Failed to save uploaded file: {}", e))
    })?;

    info!("Saved uploaded video to {:?}. Enqueuing transcode job.", temp_path);

    // Submit to background transcoding queue
    state.video_service.submit_to_transcode(&video.id, temp_path).await
        .map_err(|e| err_response(StatusCode::INTERNAL_SERVER_ERROR, &format!("Queue error: {}", e)))?;

    Ok((StatusCode::CREATED, Json(UploadResponse {
        id: video.id,
        title: video.title,
        status: video.status.as_str().to_string(),
    })))
}

pub async fn list_videos(
    State(state): State<AppState>,
) -> impl IntoResponse {
    match state.video_service.list_videos().await {
        Ok(videos) => Json(videos).into_response(),
        Err(e) => err_response(StatusCode::INTERNAL_SERVER_ERROR, &format!("Database error: {}", e)),
    }
}

pub async fn get_video(
    State(state): State<AppState>,
    Path(id): Path<String>,
) -> impl IntoResponse {
    match state.video_service.get_video(&id).await {
        Ok(Some(video)) => {
            let chapters = state.video_service.get_chapters(&id).await.unwrap_or_default();
            Json(serde_json::json!({
                "video": video,
                "chapters": chapters
            })).into_response()
        }
        Ok(None) => err_response(StatusCode::NOT_FOUND, "Video not found"),
        Err(e) => err_response(StatusCode::INTERNAL_SERVER_ERROR, &format!("Database error: {}", e)),
    }
}

pub async fn delete_video(
    State(state): State<AppState>,
    Path(id): Path<String>,
) -> impl IntoResponse {
    match state.video_service.delete_video(&id).await {
        Ok(_) => StatusCode::NO_CONTENT.into_response(),
        Err(e) => err_response(StatusCode::INTERNAL_SERVER_ERROR, &e),
    }
}

pub async fn track_event(
    State(state): State<AppState>,
    Json(payload): Json<TrackEventRequest>,
) -> impl IntoResponse {
    let event = AnalyticsEvent {
        id: None,
        video_id: payload.video_id,
        event_type: payload.event_type,
        session_id: payload.session_id,
        watch_time: payload.watch_time.unwrap_or(0.0),
        buffer_count: payload.buffer_count.unwrap_or(0),
        buffer_duration: payload.buffer_duration.unwrap_or(0.0),
        seek_count: payload.seek_count.unwrap_or(0),
        playback_speed: payload.playback_speed.unwrap_or(1.0),
        completion_percentage: payload.completion_percentage.unwrap_or(0.0),
        device_type: payload.device_type,
        network_speed: payload.network_speed,
        error_message: payload.error_message,
        created_at: None,
    };

    match state.analytics_service.track_event(event).await {
        Ok(_) => StatusCode::OK.into_response(),
        Err(e) => err_response(StatusCode::INTERNAL_SERVER_ERROR, &format!("Database error: {}", e)),
    }
}

pub async fn get_global_analytics(
    State(state): State<AppState>,
) -> impl IntoResponse {
    match state.analytics_service.get_global_stats().await {
        Ok(stats) => Json(stats).into_response(),
        Err(e) => err_response(StatusCode::INTERNAL_SERVER_ERROR, &format!("Database error: {}", e)),
    }
}

pub async fn get_video_analytics(
    State(state): State<AppState>,
    Path(id): Path<String>,
) -> impl IntoResponse {
    match state.analytics_service.get_video_stats(&id).await {
        Ok(Some(stats)) => Json(stats).into_response(),
        Ok(None) => err_response(StatusCode::NOT_FOUND, "Video analytics not found"),
        Err(e) => err_response(StatusCode::INTERNAL_SERVER_ERROR, &format!("Database error: {}", e)),
    }
}

