// Custom handler for streaming files (m3u8, ts, poster.jpg, sprite.vtt, sprites)
pub async fn serve_hls_stream(
    State(state): State<AppState>,
    Path((id, file)): Path<(String, String)>,
) -> impl IntoResponse {
    let video = match state.video_service.get_video(&id).await {
        Ok(Some(v)) => v,
        Ok(None) => return err_response(StatusCode::NOT_FOUND, "Video not found"),
        Err(e) => return err_response(StatusCode::INTERNAL_SERVER_ERROR, &format!("Database error: {}", e)),
    };

    // Check if the requested file is a .ts segment and if we are in Mock/Failed status 
    // or if we just want to redirect segments to avoid generating/serving huge files
    if file.ends_with(".ts") {
        // Look at the DB status to determine if we redirect.
        // We also redirect if no local segment file exists to prevent player crash
        let local_file_path = state.storage.get_video_stream_dir(&id).join(&file);
        if !local_file_path.exists() {
            // Check if it's a mock segment structure like segment_720p_000.ts or segment_480p_000.ts
            // Mux's segments are named segment_0.ts, segment_1.ts, etc.
            // Let's parse out the number.
            let parts: Vec<&str> = file.split('_').collect();
            if parts.len() >= 3 {
                if let Some(num_part) = parts.last() {
                    let num_str = num_part.trim_end_matches(".ts");
                    if let Ok(num) = num_str.parse::<i32>() {
                        // Limit segment number to 12 since Mux's sample stream has 12 segments
                        let target_num = num % 13;
                        let target_url = format!("https://test-streams.mux.dev/pts_shift/segment_{}.ts", target_num);
                        info!("Redirecting mock segment request {} to {}", file, target_url);
                        return Redirect::temporary(&target_url).into_response();
                    }
                }
            }
            // Fallback redirect if structure didn't match
            return Redirect::temporary("https://test-streams.mux.dev/pts_shift/segment_0.ts").into_response();
        }
    }

    // Serve local file
    let file_path = state.storage.get_video_stream_dir(&id).join(&file);
    if !file_path.exists() {
        return err_response(StatusCode::NOT_FOUND, "File not found");
    }

    match fs::read(&file_path).await {
        Ok(bytes) => {
            let mut headers = HeaderMap::new();
            
            // Determine Content-Type
            let mime = if file.ends_with(".m3u8") {
                "application/x-mpegURL"
            } else if file.ends_with(".ts") {
                "video/MP2T"
            } else if file.ends_with(".jpg") || file.ends_with(".jpeg") {
                "image/jpeg"
            } else if file.ends_with(".vtt") {
                "text/vtt"
            } else {
                "application/octet-stream"
            };

            headers.insert(header::CONTENT_TYPE, mime.parse().unwrap());
            // Support CORS for media playing
            headers.insert(header::ACCESS_CONTROL_ALLOW_ORIGIN, "*".parse().unwrap());

            (StatusCode::OK, headers, bytes).into_response()
        }
        Err(e) => {
            error!("Failed to read stream file {:?}: {:?}", file_path, e);
            err_response(StatusCode::INTERNAL_SERVER_ERROR, "Failed to read stream file")
        }
    }
}
